# Merge without overwriting existing manually refined keys
merged_count = 0
for k, v in NEW_BRANDS.items():
    if k not in current_brands:
        current_brands[k] = v
        merged_count += 1
    else:
        # Update indication or class if empty
        for sub_k in ["salt", "class", "typical_use"]:
            if not current_brands[k].get(sub_k):
                current_brands[k][sub_k] = v[sub_k]

print(f"Added {merged_count} new brands. Total brands now: {len(current_brands)}")
